// Requires `identifierPrefix` for `createRoot` of `react-dom/client`.
// When another React root (e.g. a global navigation in the header) is on the same page,
// ids generated by `useId` can collide across roots and break `htmlFor` of `label` and so on.

// Whether the identifier refers to `createRoot` imported from `react-dom/client`.
// Resolve its nearest binding so that shadowed names are not reported.
function isReactCreateRoot(context, identifier) {
  let scope = context.sourceCode.getScope(identifier);
  while (scope) {
    const variable = scope.set.get(identifier.name);
    if (variable) {
      const def = variable.defs[0];
      return (
        def?.type === "ImportBinding" &&
        def.parent.source.value === "react-dom/client" &&
        def.node.type === "ImportSpecifier" &&
        def.node.imported.type === "Identifier" &&
        def.node.imported.name === "createRoot"
      );
    }
    scope = scope.upper;
  }
  return false;
}

/** @type {import('eslint').Rule.RuleModule} */
export default {
  meta: {
    type: "problem",
    docs: {
      description: "Require `identifierPrefix` for `createRoot`",
    },
    messages: {
      missing:
        "Specify `identifierPrefix` for `createRoot`. Otherwise, ids generated by `useId` may collide with those of another React root on the same page.",
    },
    schema: [],
  },
  create(context) {
    return {
      CallExpression(node) {
        if (
          node.callee.type !== "Identifier" ||
          !isReactCreateRoot(context, node.callee)
        ) {
          return;
        }
        const options = node.arguments[1];
        if (options === undefined) {
          context.report({ node, messageId: "missing" });
          return;
        }
        // Options passed as a variable cannot be inspected, so allow them
        if (options.type !== "ObjectExpression") return;
        const hasIdentifierPrefix = options.properties.some((property) => {
          // Spread properties cannot be inspected either, so allow them
          if (property.type === "SpreadElement") return true;
          return (
            property.key.type === "Identifier" &&
            property.key.name === "identifierPrefix"
          );
        });
        if (!hasIdentifierPrefix) {
          context.report({ node, messageId: "missing" });
        }
      },
    };
  },
};
